// src/lib/mcp/tools/list-blog-posts.ts
import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.24.0";
import { z as z2 } from "npm:zod@^3.25.76";
var list_blog_posts_default = defineTool3({
  name: "list_blog_posts",
  title: "List blog posts",
  description: "List QuantumAI Lab blog articles with slug, title, category, date, read time, excerpt and URL. Optionally filter by category or a search term.",
  inputSchema: {
    category: z2.string().describe("Optional category filter, matched case-insensitively.").optional(),
    query: z2.string().describe("Optional free-text search across title and excerpt.").optional()
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ category, query }) => {
    const term = query?.trim().toLowerCase();
    const cat = category?.trim().toLowerCase();
    const posts = blogPosts.filter((post) => cat ? post.category.toLowerCase() === cat : true).filter(
      (post) => term ? `${post.title} ${post.excerpt}`.toLowerCase().includes(term) : true
    ).map((post) => ({
      slug: post.slug,
      title: post.title,
      category: post.category,
      date: post.date,
      readTime: post.readTime,
      excerpt: post.excerpt,
      author: post.author.name,
      url: `${SITE_URL}/blog/${post.slug}`
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(posts, null, 2) }],
      structuredContent: { posts, count: posts.length }
    };
  }
});

